import numpy as np
from scipy.optimize import least_squares
import warnings; warnings.filterwarnings('ignore')
t=np.asarray(df['t']);A=np.asarray(df['A']);y=np.asarray(df['dA_dt'])
def fit(f,npar,nstart=60):
    best=None
    for s in range(nstart):
        rng=np.random.default_rng(s)
        p0=rng.normal(0,0.7,npar)
        try: r=least_squares(lambda p:(f(p,t,A)-y),p0,max_nfev=3000)
        except Exception: continue
        if not np.all(np.isfinite(r.fun)): continue
        if best is None or r.cost<best.cost: best=r
    return best, np.mean((f(best.x,t,A)-y)**2)/np.var(y)
def m1(p,t,A):
